"use client"; 
import React, { useState } from 'react';
import './Contact.css';
import { Mail, Phone, Send, CheckCircle, X, ExternalLink, Linkedin } from 'lucide-react'; 
import { useForm, ValidationError } from '@formspree/react';

const Contact = () => {
  const [state, handleSubmit] = useForm("xlggjajo");
  const [isEmailModalOpen, setIsEmailModalOpen] = useState(false);
  const [copied, setCopied] = useState(false);
  const [companyType, setCompanyType] = useState(""); 

  const emailAddress = "aviram@eldarvisual.com";

  const handleCopy = () => {
    navigator.clipboard.writeText(emailAddress);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleEmailClick = (e: React.MouseEvent) => {
    e.preventDefault();
    setIsEmailModalOpen(true);
  };

  // === מצב הצלחה (Success State) ===
  if (state.succeeded) {
    return (
      <section id="contact" className="contact-section">
        <div className="contact-container">
          <div className="success-state">
            <div className="success-icon-wrapper">
              <CheckCircle size={64} className="success-check-icon" />
            </div>
            <h2 className="success-title">Message Received!</h2>
            <p className="success-desc">
              Thanks, Aviram here. I'll review your details and get back to you within 24 hours.
            </p>
            
            <div className="success-actions">
              <button 
                onClick={() => window.location.href = '#home'} 
                className="success-btn-primary"
              >
                Back to Home
              </button>
              <a 
                href="https://www.linkedin.com/in/aviram-eldar/" 
                target="_blank" 
                rel="noopener noreferrer" 
                className="success-btn-secondary"
              >
                <Linkedin size={18} /> View My LinkedIn
              </a>
            </div>
          </div>
        </div>
      </section>
    );
  }

  // === מצב טופס רגיל ===
  return (
    <section id="contact" className="contact-section">
      <div className="contact-container">
        
        <div className="contact-grid">
          
          {/* צד שמאל - מידע */}
          <div className="info-side">
            <span className="section-label">Let's Talk</span>
            <h2 className="main-title">Ready to build something <span className="gradient-text">Extraordinary?</span></h2>
            <p className="info-desc">
              Whether you're looking for a high-performance website, a UX audit, or full-scale management, I'm here to help.
            </p>

            <div className="contact-methods">
              <div className="method-item" onClick={handleEmailClick} style={{cursor: 'pointer'}}>
                <div className="icon-box blue"><Mail size={24} /></div>
                <div className="method-text">
                  <span>Email Me</span>
                  <strong>{emailAddress}</strong>
                </div>
              </div>
            </div>
          </div>

          {/* צד ימין - הטופס */}
          <div className="form-side">
            <form onSubmit={handleSubmit} className="premium-form">
              <div className="form-group">
                <label>Full Name</label>
                <div className="form-wrapper">
                  <input type="text" name="name" placeholder="John Doe" required />
                </div>
              </div>

              <div className="form-group">
                <label>Work Email</label>
                <div className="form-wrapper">
                  <input type="email" name="email" placeholder="john@company.com" required />
                </div>
                <ValidationError prefix="Email" field="email" errors={state.errors} />
              </div>

              <div className="form-row">
                <div className="form-group">
                  <label>Company Type</label>
                  <div className="form-wrapper">
                    <select 
                      name="company" 
                      value={companyType} 
                      onChange={(e) => setCompanyType(e.target.value)}
                      required
                    >
                      <option value="" disabled>Select...</option>
                      <option value="startup">Startup</option>
                      <option value="enterprise">Enterprise</option>
                      <option value="agency">Agency</option>
                      <option value="personal">Personal Brand</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="form-group">
                <label>How can I help?</label>
                <div className="form-wrapper">
                  <textarea name="message" placeholder="Tell me about your project goals..." required />
                </div>
              </div>

              <button type="submit" disabled={state.submitting} className="submit-btn">
                <span>{state.submitting ? 'Sending...' : 'Get My Free Audit'}</span>
                <Send size={18} />
              </button>
            </form>
          </div>
        </div>
      </div>

      {/* Email Provider Modal */}
      {isEmailModalOpen && (
        <div className="modal-overlay" onClick={() => setIsEmailModalOpen(false)}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close" onClick={() => setIsEmailModalOpen(false)}><X size={20}/></button>
            <h3 className="modal-title">Choose Email Provider</h3>
            
            <div className="provider-list">
              <a href={`https://mail.google.com/mail/?view=cm&fs=1&to=${emailAddress}`} target="_blank" rel="noopener noreferrer" className="provider-btn">
                Gmail <ExternalLink size={14}/>
              </a>
              <a href={`https://outlook.live.com/mail/0/deeplink/compose?to=${emailAddress}`} target="_blank" rel="noopener noreferrer" className="provider-btn">
                Outlook <ExternalLink size={14}/>
              </a>
              <button onClick={handleCopy} className="provider-btn">
                {copied ? 'Copied!' : 'Copy Email Address'}
              </button>
              <a href={`mailto:${emailAddress}`} className="provider-btn" style={{borderColor: '#A855F7', color: '#A855F7'}}>
                Open Default App
              </a>
            </div>
          </div>
        </div>
      )}
    </section>
  );
};

export default Contact;