"use client"; 
import React from 'react';
import Image from 'next/image';
import { ArrowRight } from 'lucide-react';
import styles from './Hero.module.css'; // תיקון האות הגדולה H
import dynamic from 'next/dynamic';

// טעינה דינמית לשיפור LCP
const ScrollContent = dynamic(() => import('./ScrollContent'), {
  ssr: false,
  loading: () => <div className={styles.skeletonLoader} />
});

// Helper Components לבלוק הקוד ברקע
const Keyword = ({ t }: { t: string }) => <span className={styles.tokenKeyword}>{t}</span>; 
const Func = ({ t }: { t: string }) => <span className={styles.tokenFunc}>{t}</span>; 
const StringVal = ({ t }: { t: string }) => <span className={styles.tokenString}>{t}</span>; 
const Var = ({ t }: { t: string }) => <span className={styles.tokenVar}>{t}</span>; 
const Prop = ({ t }: { t: string }) => <span className={styles.tokenProp}>{t}</span>; 
const Punct = ({ t }: { t: string }) => <span className={styles.tokenPunct}>{t}</span>; 
const Comment = ({ t }: { t: string }) => <span className={styles.tokenComment}>{t}</span>; 

const CodeLine = ({ children }: { children: React.ReactNode }) => (
  <div className={styles.codeLine}>{children}</div>
);

const CodeBlock = () => (
    <div className={styles.codeBlock}>
      <CodeLine><Comment t="// Initializing core render loop" /></CodeLine>
      <CodeLine><Keyword t="const" /> <Func t="animateFrame" /> <Keyword t="=" /> <Keyword t="async" /> (<Var t="delta" />) <Keyword t="=>" /> <Punct t="{" /></CodeLine>
      <CodeLine>  <Keyword t="await" /> <Var t="renderer" />.<Func t="update" />(<Var t="scene" />, <Var t="velocity" />);</CodeLine>
      <CodeLine>  <Keyword t="return" /> <Var t="Masterpiece" />.<Func t="render" />(<Punct t="{" /><Prop t="pixelPerfect" />: <Keyword t="true" /><Punct t="}" />);</CodeLine>
      <CodeLine><Punct t="}" />;</CodeLine>
    </div>
);

interface HeroProps {
  title?: React.ReactNode;
  subtitle?: string;
  ctaText?: string;
  trustLine?: string;
}

export default function Hero({ 
  title, 
  subtitle = "High-performance websites built with modern frameworks. Faster loading, better UX, and built for long-term growth. No templates, no bloat.",
  ctaText = "Start with a Website Review",
  trustLine = "Performance-focused | UX-driven | Built to last"
}: HeroProps) {

  const scrollToSection = (e: React.MouseEvent, id: string) => {
    e.preventDefault();
    const element = document.getElementById(id);
    if (element) {
        element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  // שימוש ב-Styles Modules לכותרת
  const finalTitle = title || (
    <>
      <span className={styles.titlePart1}>Modern Websites. </span>
      <span className={styles.titlePart2}>Clean Code. </span>
      <span className={`${styles.titlePart3} ${styles.heroTitleGradient}`}>Real Results.</span>
    </>
  );

  return (
    <section id="hero" className={styles.heroSection}>
      
      <div className={styles.heroBgBlobs}>
        <div className={styles.blobBlue} />
        <div className={styles.blobPurple} />
      </div>

      <div className={styles.heroCodeBg}>
         <div className={styles.codeRotateWrapper}>
           {Array.from({ length: 2 }).map((_, i) => (
             <CodeBlock key={i} />
           ))}
         </div>
      </div>

      <div className={styles.heroContent}>
        
        <div className={styles.mobileImageContainer}>
            <Image 
                src="/floatForWeb.webp" 
                alt="UI/UX Design Illustration" 
                width={600} 
                height={400}
                priority
            />
        </div>
      
        <div className={styles.heroTextSide}>
          <h1 className={styles.heroTitle}>
            {finalTitle}
          </h1> 
          
          <div className={`${styles.heroSubtitleGroup} ${styles.delay1}`}>
            <p className={styles.heroSubtitle}>
              {subtitle}
            </p>
          </div>

          <div className={`${styles.heroActions} ${styles.delay2}`}>
            <button onClick={(e) => scrollToSection(e, 'contact')} className={styles.btnPrimary}>
              {ctaText}
            </button>
            <button onClick={(e) => scrollToSection(e, 'portfolio')} className={`${styles.btnLink} ${styles.group}`}>
              <span>View Projects</span>
              <ArrowRight size={16} className={styles.arrowIcon} />
            </button>
          </div>

          <p className={styles.trustLine}>
            {trustLine}
          </p>
        </div>

        <div className={styles.heroVisualSide}>
           <div className={styles.browserMockup}>
            <div className={styles.browserWindow}>
                <div className={styles.browserHeader}>
                  <div className={styles.browserDots}>
                    <div className={styles.dot} />
                    <div className={styles.dot} />
                    <div className={styles.dot} />
                  </div>
                  <div className={styles.browserAddressBar}>eldarvisual.com</div>
                </div>
                <div className={styles.browserContentViewport}>
                   {/* החזרת התוכן הנגלל - כאן הקסם קורה */}
                   <div className={styles.scrollingContent}>
                      <ScrollContent />
                      <ScrollContent />
                   </div>
                </div>
              </div>
          </div>
        </div>

      </div>
    </section>
  );
}