"use client";
import React, { useState } from 'react';
import { Search, PenTool, Code, Rocket } from 'lucide-react';
import styles from './Process.module.css'; 

export default function Process() {
  const [activeStep, setActiveStep] = useState<number | null>(null);

  const steps = [
    { id: 1, icon: <Search />, title: "Discovery", desc: "Understanding your mission and target audience.", color: styles.cardBlue },
    { id: 2, icon: <PenTool />, title: "UX/UI Design", desc: "Crafting a visual identity that resonates.", color: styles.cardPurple },
    { id: 3, icon: <Code />, title: "Development", desc: "Building with Next.js for ultimate performance.", color: styles.cardGreen },
    { id: 4, icon: <Rocket />, title: "Launch", desc: "Going live and optimizing for growth.", color: styles.cardYellow }
  ];

  return (
    <section id="process" className={styles.processSection}>
      <div className={styles.processContainer}>
        <div className={styles.headerWrapper}>
          <span className={styles.subTitle}>The Workflow</span>
          <h2 className={styles.mainTitle}>From Concept to <span className={styles.gradientText}>Completion.</span></h2>
        </div>

        <div className={styles.stepsWrapper}>
          {steps.map((step) => (
            <div 
              key={step.id} 
              className={`${styles.stepRow} ${activeStep === step.id ? styles.active : ''}`}
              onClick={() => setActiveStep(step.id)}
            >
              <div className={styles.visualSide}>
                <div className={`${styles.cardBase} ${step.color}`}>
                   {step.icon}
                </div>
              </div>
              <div className={styles.contentSide}>
                <h3 className={styles.stepTitle}>{step.title}</h3>
                <p className={styles.stepDesc}>{step.desc}</p>
              </div>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}