"use client";
import React, { useState, useEffect } from 'react';
import styles from './Navbar.module.css';
import { Menu, X } from 'lucide-react';

const Navbar = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      <div className={`${styles.menuOverlay} ${isOpen ? styles.active : ''}`} onClick={() => setIsOpen(false)} />
      <nav className={`${styles.navbar} ${scrolled ? styles.scrolled : ''}`}>
        <div className={styles.navContainer}>
          <a href="#hero" className={styles.navLogo}>
            <span className={styles.brandName}>ELDAR<span className={styles.blueDot}>VISUAL</span></span>
          </a>

          <div className={styles.desktopMenu}>
            <a href="#services" className={styles.navLink}>Services</a>
            <a href="#process" className={styles.navLink}>Process</a>
            <a href="#portfolio" className={styles.navLink}>Portfolio</a>
          </div>

          <div className={styles.navbarCta}>
            <a href="#contact" className={styles.btnTalk}>Let's Talk</a>
          </div>

          <div className={styles.mobileToggle} onClick={() => setIsOpen(!isOpen)}>
            {isOpen ? <X size={28} /> : <Menu size={28} />}
          </div>
        </div>

        <div className={`${styles.mobileMenu} ${isOpen ? styles.active : ''}`}>
          <a href="#services" className={styles.mobileLink} onClick={() => setIsOpen(false)}>Services</a>
          <a href="#process" className={styles.mobileLink} onClick={() => setIsOpen(false)}>Process</a>
          <a href="#portfolio" className={styles.mobileLink} onClick={() => setIsOpen(false)}>Portfolio</a>
          <a href="#contact" className={`${styles.mobileLink} ${styles.highlight}`} onClick={() => setIsOpen(false)}>Let's Talk</a>
        </div>
      </nav>
    </>
  );
};

export default Navbar;